const resposta = $input.first().json;
const ok = !resposta.error && resposta.statusCode >= 200 && resposta.statusCode < 300 && Array.isArray(resposta.body);
const funis = ok ? resposta.body.filter((funil) => funil && (funil.id ?? funil._id) != null) : [];
if (funis.length === 0) return [{ json: { temFunil: false } }];
return funis.map((funil) => ({ json: { temFunil: true, funilId: String(funil.id ?? funil._id) } }));

const LIMITE_DE_PAGINAS = 60;
const TETO_DA_API = 10000;
const contexto = $('Montar requisição').first().json;
const respostaDosFunis = $('Listar funis').first().json;
const paginas = $input.all().map((item) => item.json).filter((json) => json && (json.statusCode !== undefined || json.error));
const respostas = [respostaDosFunis, ...paginas];
const requests = respostas.length;
const bytes = respostas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

const falhaDeRede = respostas.find((resposta) => resposta.error);
if (falhaDeRede) {
  const detalhe = falhaDeRede.error?.message ?? String(falhaDeRede.error);
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${detalhe}`.slice(0, 500) }]);
}

const recusada = respostas.find((resposta) => !(resposta.statusCode >= 200 && resposta.statusCode < 300));
if (recusada) {
  const corpo = recusada.body ?? {};
  const detalhe = String(corpo.error || corpo.message || `HTTP ${recusada.statusCode}`).slice(0, 500);
  const semAcesso = recusada.statusCode === 401 || recusada.statusCode === 403;
  return devolver([], [{ causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe }]);
}

const ROTULO_MAXIMO = 200;
const texto = (valor) => {
  if (typeof valor !== 'string' && typeof valor !== 'number') return null;
  const limpo = String(valor).trim();
  return limpo ? limpo.slice(0, ROTULO_MAXIMO) : null;
};
const identificador = (valor) => {
  const id = texto(valor);
  return id && /^[A-Za-z0-9_-]+$/.test(id) ? id : null;
};
const numero = (valor) => {
  if (valor === null || valor === undefined || valor === '') return null;
  const convertido = Number(valor);
  return Number.isFinite(convertido) ? convertido : null;
};
const booleano = (valor) => (typeof valor === 'boolean' ? valor : null);
const instante = (valor) => (typeof valor === 'string' && valor ? valor : null);

const etapas = new Map();
for (const funil of Array.isArray(respostaDosFunis.body) ? respostaDosFunis.body : []) {
  const pipelineId = identificador(funil?.id ?? funil?._id);
  for (const etapa of Array.isArray(funil?.deal_stages) ? funil.deal_stages : []) {
    const etapaId = identificador(etapa?.id ?? etapa?._id);
    if (!etapaId) continue;
    etapas.set(etapaId, { pipelineId, pipelineName: texto(funil.name), stageOrder: numero(etapa.order) });
  }
}

function linhaDa(negociacao) {
  const dealId = identificador(negociacao?.id ?? negociacao?._id);
  if (!dealId) return null;
  const etapa = negociacao.deal_stage ?? {};
  const stageId = identificador(etapa.id ?? etapa._id);
  const doFunil = (stageId && etapas.get(stageId)) || {};
  return {
    dealId,
    pipelineId: doFunil.pipelineId ?? null,
    pipelineName: doFunil.pipelineName ?? null,
    stageId,
    stageName: texto(etapa.name),
    stageOrder: doFunil.stageOrder ?? null,
    win: booleano(negociacao.win),
    hold: booleano(negociacao.hold),
    amountTotal: numero(negociacao.amount_total),
    amountMonthly: numero(negociacao.amount_montly ?? negociacao.amount_monthly),
    amountUnique: numero(negociacao.amount_unique),
    createdAt: instante(negociacao.created_at),
    updatedAt: instante(negociacao.updated_at),
    closedAt: instante(negociacao.closed_at),
    dealSourceName: texto(negociacao.deal_source?.name),
    campaignName: texto(negociacao.campaign?.name),
  };
}

const porId = new Map();
const porFunil = new Map();
for (const pagina of paginas) {
  const negociacoes = Array.isArray(pagina.body?.deals) ? pagina.body.deals : [];
  const linhasDaPagina = negociacoes.map(linhaDa).filter(Boolean);
  for (const linha of linhasDaPagina) porId.set(linha.dealId, linha);
  const funil = linhasDaPagina[0]?.pipelineId ?? 'sem_funil';
  const resumo = porFunil.get(funil) ?? { paginas: 0, coletadas: 0, total: 0, temMais: false };
  resumo.paginas += 1;
  resumo.coletadas += linhasDaPagina.length;
  resumo.total = Math.max(resumo.total, Number(pagina.body?.total ?? 0));
  resumo.temMais = resumo.temMais || pagina.body?.has_more === true;
  porFunil.set(funil, resumo);
}

const linhas = [...porId.values()];
if (linhas.length === 0) return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }]);

const truncados = [...porFunil.entries()].filter(([, resumo]) =>
  (resumo.paginas >= LIMITE_DE_PAGINAS && resumo.temMais) || (resumo.coletadas >= TETO_DA_API && resumo.coletadas < resumo.total));
if (truncados.length > 0) {
  const detalhe = truncados.map(([funil, resumo]) => `${funil}: ${resumo.coletadas}/${resumo.total}`).join('; ');
  return devolver(linhas, [{ causa: 'coleta_incompleta', detalhe: `funil acima do teto de paginação: ${detalhe}`.slice(0, 500) }]);
}

return devolver(linhas, []);
